# 어그 공식 사이즈 정보(ugg.com)의 남녀공용 표(US Women's·US Men's·UK·EU·Japan cm). 여성 = 남성 + 1.
_UGG = [(220, 4, 3, 36), (225, 4.5, 3.5, 36.5), (230, 5, 4, 37), (235, 5.5, 4.5, 37.5), (240, 6, 5, 38),
        (245, 6.5, 5.5, 38.5), (250, 7, 6, 39.5), (255, 7.5, 6.5, 40), (260, 8, 7, 40.5), (265, 8.5, 7.5, 41),
        (270, 9, 8, 42), (275, 9.5, 8.5, 42.5), (280, 10, 9, 43), (285, 10.5, 9.5, 43.5), (290, 11, 10, 44),
        (295, 11.5, 10.5, 44.5), (300, 12, 11, 45.5)]
