# 남성표는 EU 39(250)부터, 여성표는 EU 43(280)까지. 235·255·275·295는 없는 사이즈다.
BIRKENSTOCK_MAP = {225: ("—", "4~4.5", 2.5, 35), 230: ("—", "5~5.5", 3.5, 36), 240: ("—", "6~6.5", 4.5, 37),
                   245: ("—", "7~7.5", 5, 38), 250: ("6~6.5", "8~8.5", 5.5, 39), 260: ("7~7.5", "9~9.5", 7, 40),
                   265: ("8~8.5", "10~10.5", 7.5, 41), 270: ("9~9.5", "11~11.5", 8, 42), 280: ("10~10.5", "12~12.5", 9, 43),
                   285: ("11~11.5", "—", 9.5, 44), 290: ("12~12.5", "—", 10.5, 45), 300: ("13~13.5", "—", 11.5, 46)}

# 팀버랜드 코리아 공식몰 사이즈 가이드(US·한국 남성·한국 여성)와 미국 공식몰 Men's Footwear 표(EU·UK·USA).
# 한국 남성 = US + 18(cm), 여성 = US + 17이라 같은 mm에서 여성 US = 남성 + 1. UK·EU는 남성표 값이다.
TIMBERLAND_MAP = {220: ("—", 5, "—", "—"), 225: ("—", 5.5, "—", "—"), 230: (5, 6, 4.5, 37.5), 235: (5.5, 6.5, 5, 38),
                  240: (6, 7, 5.5, 39), 245: (6.5, 7.5, 6, 39.5), 250: (7, 8, 6.5, 40), 255: (7.5, 8.5, 7, 41),
                  260: (8, 9, 7.5, 41.5), 265: (8.5, 9.5, 8, 42), 270: (9, 10, 8.5, 43), 275: (9.5, 10.5, 9, 43.5),
                  280: (10, 11, 9.5, 44), 285: (10.5, 11.5, 10, 44.5), 290: (11, 12, 10.5, 45),
                  295: (11.5, "—", 11, 45.5), 300: (12, "—", 11.5, 46)}

# 크록스 코리아 공식 사이즈 차트(한국 mm·미국 M/W·유럽·영국). 10mm 단위이고 260과 270 사이에만 265가 있다.
# M 숫자에 18을 더하는 계산은 M9(270)부터만 맞는다(M8 = 265, M7 = 260). UK는 남성 표기(여성은 1 크다).
CROCS_MAP = {220: (3, 5, 1, 35), 230: (4, 6, 2, "36~37"), 240: (5, 7, 3, "37~38"), 250: (6, 8, 4, "38~39"),
             260: (7, 9, 5, "39~40"), 265: (8, 10, 6, "41~42"), 270: (9, 11, 7, "42~43"), 280: (10, 12, 8, "43~44"),
             290: (11, "—", 9, "45~46"), 300: (12, "—", 10, "46~47")}

# 닥터마틴 코리아 공식 사이즈 가이드(한국 mm·UK)와 미국 공식 사이즈 가이드(UK·EU·US 남성·US 여성). UK 정수 사이즈만 판다.
DRM_MAP = {220: (4, 5, 3, 36), 230: (5, 6, 4, 37), 240: (6, 7, 5, 38), 250: (7, 8, 6, 39), 260: (8, 9, 7, 41),
           270: (9, 10, 8, 42), 280: (10, 11, 9, 43), 290: (11, 12, 10, 45), 300: (12, 13, 11, 46)}

# 공식표를 대조한 브랜드는 브랜드 사이즈표 페이지(build_guides.py)가 있고, 모델 페이지 경로에 끼운다.
BRAND_HUBS = {"나이키": "nike-size-chart", "아디다스": "adidas-size-chart", "뉴발란스": "newbalance-size-chart",
              "반스": "vans-size-chart", "컨버스": "converse-size-chart"}

BRAND_CHARTS = {
    "나이키": (NIKE_MAP, "나이키 공식 사이즈표"),
    "아디다스": (ADIDAS_MAP, "아디다스 공식 사이즈표"),
    "뉴발란스": (NB_MAP, "뉴발란스 공식 사이즈표"),
    "반스": (VANS_MAP, "반스 공식 사이즈표"),
    "아식스": (ASICS_MAP, "아식스 공식 사이즈표"),
    "오니츠카": (ASICS_MAP, "오니츠카 타이거 공식 사이즈표"),
    "푸마": (PUMA_MAP, "푸마 공식 사이즈표"),
    "리복": (REEBOK_MAP, "리복 공식 사이즈표"),
    "살로몬": (ADIDAS_MAP, "살로몬 공식 사이즈표"),
    "온": (ON_MAP, "온 공식 사이즈표"),
    "어그": (UGG_MAP, "어그 공식 사이즈표"),
    "버켄스탁": (BIRKENSTOCK_MAP, "버켄스탁 공식 사이즈표"),
    "팀버랜드": (TIMBERLAND_MAP, "팀버랜드 공식 사이즈표"),
    "크록스": (CROCS_MAP, "크록스 코리아 공식 사이즈표"),
    "닥터마틴": (DRM_MAP, "닥터마틴 공식 사이즈표"),
}

# 남녀공용 표기가 없어 US 여성 칸을 여성 사이즈표의 같은 mm 값으로 채운 브랜드.
W_FROM_WOMENS = {"온", "팀버랜드"}


def chart_for(m):
    """모델에 맞는 (환산표, 출처 문구). 공식표를 대조하지 않은 브랜드는 일반 환산표."""
    if m.get("converse_chart"):
        return CONVERSE_MAP, "컨버스 공식 사이즈표"
    return BRAND_CHARTS.get(m["name"].split()[0], (MAP, None))


def num(n):
    if isinstance(n, str):
        return n
    return str(int(n)) if float(n) == int(n) else str(n)


def keep_phrases(text):
    """결론 문구에서 줄이 끊기면 안 되는 곳을 <span class="nw">로 묶는다. 글자는 바꾸지 않는다.
    - '반 사이즈 업'·'발볼 넓으면' 같은 구, 짧은 가운뎃점 단어('미드·하이는')는 통째로
    - 긴 가운뎃점 목록은 '나이키·'처럼 점 뒤에서만 끊기게
    - 연산자는 뒤 항과 붙여 줄 끝에 '='·'−'가 홀로 남지 않게"""
    nw = lambda m: f'<span class="nw">{m.group(0)}</span>'
    text = re.sub(r"[반한] 사이즈 (?:업|다운)|발볼 (?:넓으면|있으면)", nw, text)
    text = re.sub(r"(?<![^\s(])[^\s·<>]+(?:·[^\s·<>]+)+",
                  lambda m: nw(m) if len(m.group(0)) <= 10 else re.sub(r"[^\s·<>]+·", nw, m.group(0)), text)
    text = re.sub(r"[=−~+] [^\s<>]{1,12}(?: [\d.]+)?(?=\s|$)", nw, text)
    # 뒤 항이 이미 묶여 있으면 연산자를 그 묶음 안으로 넣는다 ('= 235mm(아디다스·')
    text = re.sub(r'([=−~+]) <span class="nw">', r'<span class="nw">\1 ', text)
    return text


def eun_neun(word):
    """단어 끝 글자의 받침을 보고 '은' 또는 '는'을 돌려준다. 숫자·영문도 읽는 소리로 판단."""
    ch = word.strip()[-1]
    if "가" <= ch <= "힣":
        return "은" if (ord(ch) - 0xAC00) % 28 else "는"
    if ch.isdigit():
        return "는" if ch in "2459" else "은"   # 이·사·오·구 = 받침 없음
    if ch.upper() in "LMNR":                    # 엘·엠·엔·알 = 받침 있음
        return "은"
    return "는"


def build(m, others):
    # 정사이즈 모델은 '권장 mm'가 '평소 사이즈'와 값이 같다.
    # 같은 숫자를 두 번 보여주면 표만 넓어지고 읽는 사람은 헷갈린다.
    # 사이즈 간격이 넓은 모델("round")은 사이에 걸리는 줄에 본문 안내대로 작은(큰) 사이즈를 적는다.
    # 그 줄은 평소 사이즈와 값이 달라지니 권장 mm 열을 남긴다.
    rnd = m.get("round")
    same = (m["offset"] == 0 and not rnd)

    chart, chart_src = chart_for(m)
    rows = ""
    for mm in SIZES:
        rec = mm + m["offset"]
        if rnd and rec not in chart:
            rec = max(k for k in chart if k < rec) if rnd == "down" else min(k for k in chart if k > rec)
        us, usw, uk, eu = chart.get(rec, ("—", "—", "—", "—"))
        pick = "" if same else f'<td class="rec">{rec}</td>'
        rows += (f'<tr data-mm="{mm}"><th scope="row">{mm}</th>{pick}'
                 f'<td>{num(us)}</td><td>{num(usw)}</td><td>{num(uk)}</td><td>{num(eu)}</td></tr>\n          ')

    head_cells = '<th scope="col">평소 사이즈</th>'
    if not same:
        head_cells += '<th scope="col">권장 mm</th>'
    head_cells += ('<th scope="col">US 남성</th><th scope="col">US 여성</th>'
                   '<th scope="col">UK</th><th scope="col">EU</th>')
    caption = (f"US·UK·EU는 권장 사이즈를 {chart_src}에 대조한 값입니다."
               if chart_src else
               "US·UK·EU는 일반 환산표 기준이며, 이 브랜드 공식표와는 0.5 정도 차이가 날 수 있습니다.")
    brand = m["name"].split()[0]
    if brand in W_FROM_WOMENS:
        caption += f" US 여성은 {brand} 여성 사이즈표에서 같은 mm의 값이고, UK·EU는 남성표 기준입니다."
    else:
        caption += " US 여성은 남녀공용 상품 기준입니다. 여성 전용 상품은 브랜드 여성 사이즈표를 따로 확인하세요(같은 mm에서 0.5 정도 차이가 납니다)."
    if rnd:
        caption += f" 사이즈 간격이 넓어, 평소 사이즈가 사이에 걸리면 {'작은' if rnd == 'down' else '큰'} 사이즈를 적었습니다."
    if "<td>—</td>" in rows:
        caption += " —는 표에 없는 사이즈입니다."

    table_intro = (f"{m['name']}{eun_neun(m['name'])} 정사이즈라 표기 사이즈를 그대로 고르면 됩니다. "
                   "아래는 평소 사이즈에 해당하는 각국 사이즈입니다."
                   if same else
                   f"왼쪽이 평소 신는 사이즈, 오른쪽이 {m['name']}에서 주문할 사이즈입니다.")

    widths = "".join(
        f'<div class="width-row"><dt>{w}</dt><dd>{t}</dd></div>\n      '
        for w, t in m["widths"])

    width_note = ""
    if m["slug"].startswith("newbalance-"):
        width_note = (
            '\n    <p class="width-guide-link">뉴발란스는 같은 길이에서도 폭을 고를 수 있습니다. '
            '<a href="/newbalance-width/">D·2E·4E 발볼 가이드</a>에서 '
            '내 발 너비에 맞는 폭을 mm로 확인하세요.</p>')

    body = "".join(
        f'<h3>{h}</h3>\n    <p>{p}</p>\n    ' for h, p in m["body"])

    faq = "".join(
        f'<details{" open" if i == 0 else ""}>\n      <summary>{q}</summary>\n'
        f'      <p>{a}</p>\n    </details>\n    '
        for i, (q, a) in enumerate(m["faq"]))

    rel = "".join(
        f'<a href="/{o["slug"]}/">{o["name"]} 사이즈<span>{o["verdict"]}</span></a>\n      '
        for o in others)

    ld = json.dumps({
        "@context": "https://schema.org", "@type": "FAQPage",
        "mainEntity": [{"@type": "Question", "name": q,
                        "acceptedAnswer": {"@type": "Answer", "text": a}}
                       for q, a in m["faq"]]
    }, ensure_ascii=False, indent=2)


    hub = BRAND_HUBS.get(brand)
    trail = [("사이즈 자", "")] + ([(f"{brand} 사이즈표", f"{hub}/")] if hub else []) + [(m["name"], f"{m['slug']}/")]
    bc = json.dumps({
        "@context": "https://schema.org", "@type": "BreadcrumbList",
        "itemListElement": [{"@type": "ListItem", "position": i, "name": n, "item": f"https://sizeruler.com/{u}"}
                            for i, (n, u) in enumerate(trail, 1)]
    }, ensure_ascii=False, indent=2)
    crumb_hub = f' / <a href="/{hub}/">{brand} 사이즈표</a>' if hub else ""

    srcs = " · ".join(m["sources"])

    # 결론이 길면 글자 크기를 한 단계 줄인다 (표시만 바뀌고 문구는 그대로).
    vlen = len(m["verdict"])
    vcls = " is-xlong" if vlen > 26 else " is-long" if vlen > 14 else ""
    # 권장 mm 열에 올림·내림 방향 표시를 붙이기 위한 표 클래스
    tcls = "pick-table is-up" if m["offset"] > 0 else "pick-table is-down" if m["offset"] < 0 else "pick-table"

    finder_js = FINDER_JS

    return f"""<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{m['title']}</title>
<meta name="description" content="{m['desc']}">
<link rel="canonical" href="https://sizeruler.com/{m['slug']}/">
<meta property="og:title" content="{m['title']}">
<meta property="og:description" content="{m['desc']}">
<meta property="og:type" content="article">
<meta property="og:url" content="https://sizeruler.com/{m['slug']}/">
<meta property="og:image" content="https://sizeruler.com/og-image.png">
<meta property="og:image:width" content="1200">
<meta property="og:image:height" content="630">
<meta property="og:site_name" content="사이즈 자">
<meta name="twitter:card" content="summary_large_image">
<meta name="theme-color" content="#FFCE00">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Barlow+Semi+Condensed:wght@500;600&display=swap" rel="stylesheet">
<link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css">
<link rel="icon" href="/favicon.svg" type="image/svg+xml">
<link rel="stylesheet" href="/style.css?v=4">
<script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-8018650083353602" crossorigin="anonymous"></script>

<script type="application/ld+json">
{bc}
</script>
<script type="application/ld+json">
{ld}
</script>
</head>
<body>

<header class="masthead">
  <div class="wrap mark">
    <b><a href="/" style="text-decoration:none;color:inherit">사이즈 자</a></b>
    <span>{m['name']}</span>
  </div>
</header>

<main class="wrap">

  <p class="crumb"><a href="/">전체 환산표</a>{crumb_hub} / {m['name']}</p>

  <div class="lead">

  <div class="hero">
    <p class="eyebrow">모델별 사이즈 가이드</p>
    <h1>{m['name']} 사이즈,<br><em>어떻게 골라야 할까</em></h1>
  </div>

  <div class="verdict{vcls}">
    <div class="verdict-top">결론</div>
    <div class="verdict-body">
      <strong>{keep_phrases(m['verdict'])}</strong>
      <p>{m['verdict_sub']}</p>
    </div>
  </div>

  <section>
    <h2>평소 사이즈별 권장 사이즈</h2>
    <p>{table_intro} 평소 사이즈를 모른다면 <a href="/foot-length-chart/">발 길이로 사이즈 찾기</a>를 참고하세요.</p>
    <div class="entry">
      <label for="mmFind">평소 사이즈</label>
      <input id="mmFind" type="number" inputmode="numeric" min="225" max="290" step="5"
             placeholder="270" aria-describedby="mmFindHint">
      <span class="hint" id="mmFindHint">입력하면 해당 줄을 표시합니다</span>
      <span class="warn" id="mmFindWarn" hidden>표 범위를 벗어났습니다</span>
    </div>
    <div class="scroller">
      <table class="{tcls}">
        <caption>{caption}</caption>
        <thead>
          <tr>{head_cells}</tr>
        </thead>
        <tbody>
          {rows.rstrip()}
        </tbody>
      </table>
    </div>
  </section>

  <section>
    <h2>발볼별 가이드</h2>
    <dl class="width-grid">
      {widths.rstrip()}
    </dl>{width_note}
  </section>

  </div>

  <section class="notes">
    <h2>알아둘 점</h2>
    {body.rstrip()}
  </section>

  <section>
    <h2>자주 묻는 것</h2>
    {faq.rstrip()}
  </section>

  <section>
    <h2>다른 모델</h2>
    <div class="related">
      {rel.rstrip()}
      <a href="/">전체 신발 사이즈 환산표<span>mm · US · UK · EU · JP</span></a>
    </div>
  </section>

</main>

<footer class="wrap">
  <div>사이즈 자 — {m['name']} 사이즈 가이드</div>
  <p class="disclaimer">근거: {srcs}. 착용 경향은 모델과 생산 시기에 따라 달라질 수 있으며, 개인의 발 모양에 따라 결과가 다를 수 있습니다. 고가 제품은 매장에서 신어보고 구매하시기를 권합니다.</p>
  <p class="disclaimer"><a href="/about/">사이트 소개</a> · <a href="/privacy/">개인정보처리방침</a></p>
</footer>

{finder_js}

</body>
</html>
"""


if __name__ == "__main__":
    # 줄바꿈 도우미 점검: 글자는 그대로 두고 묶을 곳만 묶는다
    for s, spans in [("대부분 반 사이즈 업", 1), ("로우는 정사이즈, 미드·하이는 반 사이즈 업", 2),
                     ("정사이즈, 발볼 넓으면 반 사이즈 업", 2),
                     ("반 사이즈(5mm) 업", 0), ("270mm = US 9 (나이키·아디다스·뉴발란스·반스), 컨버스만 US 8.5", 4),
                     ("호수 = 손가락 둘레(mm) − 43", 2),
                     ("EU 38 = 235mm(아디다스·뉴발란스) ~ 245mm(컨버스)", 2)]:
        out = keep_phrases(s)
        assert re.sub(r"<[^>]+>", "", out) == s, out
        assert out.count('class="nw"') == spans, out

    # 젤카야노 14·젤-1130 문구: 아식스는 250mm가 US 6.5, 285mm가 US 11로 나이키와 반 칸 다르다.
    assert ASICS_MAP[270][0] == NIKE_MAP[270][0] == 9
    assert (ASICS_MAP[250][0], NIKE_MAP[250][0], ASICS_MAP[285][0], NIKE_MAP[285][0]) == (6.5, 7, 11, 10.5)

    # 공식표로 바꾼 브랜드의 본문 문구 (2026-09-28)
    assert PUMA_MAP[270] == (9, 10.5, 8, 42) and ADIDAS_MAP[270][0] == 9 and ADIDAS_MAP[270][2:] == (8.5, "42⅔")  # 푸마 스웨이드
    assert REEBOK_MAP[270] == (9, 10.5, 8, 42)                                                                   # 리복 클럽 C
    assert all(REEBOK_MAP[mm][0] == NIKE_MAP[mm][0] == ADIDAS_MAP[mm][0] for mm in range(245, 305, 5))
    assert ON_MAP[270][0] == NIKE_MAP[270][0] and ON_MAP[270][3] == NIKE_MAP[270][3] == 42.5 \
        and ON_MAP[270][2] == NIKE_MAP[270][2] + 0.5 == 8.5                                                    # 온 클라우드 5
    assert [TIMBERLAND_MAP[mm][0] for mm in (260, 265, 270, 280)] == [8, 8.5, 9, 10] and TIMBERLAND_MAP[260][1] == 9
    assert [UGG_MAP[mm][1] for mm in (230, 240, 250, 260)] == [6, 7, 8, 9] \
        and [UGG_MAP[mm][0] for mm in (260, 270, 280)] == [8, 9, 10]                                           # 어그 두 모델
    assert [BIRKENSTOCK_MAP[mm][3] for mm in (260, 265, 270, 280, 285, 290)] == [40, 41, 42, 43, 44, 45] \
        and 275 not in BIRKENSTOCK_MAP and BIRKENSTOCK_MAP[270][:3] == ("9~9.5", "11~11.5", 8)                  # 버켄스탁 보스턴
    # 여성표에서 채운 브랜드는 같은 mm에서 여성 US = 남성 + 1
    assert all(w == m + 1 for c in (ON_MAP, TIMBERLAND_MAP) for m, w, _, _ in c.values() if "—" not in (m, w))
    # 크록스: 본문 표기와 'M + 18은 M9부터만' 문구
    assert [CROCS_MAP[mm][:2] for mm in (250, 260, 265, 270, 280)] == [(6, 8), (7, 9), (8, 10), (9, 11), (10, 12)]
    assert [mm for mm, v in CROCS_MAP.items() if mm == v[0] * 10 + 180] == [270, 280, 290, 300]
    # 닥터마틴: 본문의 UK↔mm와 'UK 8 = US 남 9·여 10·EU 42'
    assert [DRM_MAP[mm][2] for mm in (260, 270, 280, 290)] == [7, 8, 9, 10] and DRM_MAP[270] == (9, 10, 8, 42)
    # 반올림 모델: 표의 모든 줄이 실제 사이즈로 채워진다
    for m in MODELS:
        if m.get("round"):
            c = chart_for(m)[0]
            assert all(min(c) <= mm + m["offset"] <= max(c) for mm in SIZES), m["slug"]

    for m in MODELS:
        brand = m["name"].split()[0]
        # 목록 순서대로 고르면 앞쪽 모델만 링크를 받는다. 자기 다음 모델부터 돌아가며 고른다.
        i = MODELS.index(m)
        pool = MODELS[i + 1:] + MODELS[:i]
        # 같은 브랜드 형제 모델을 먼저 보여준다 (사용자가 실제로 헷갈리는 조합)
        siblings = [o for o in pool if o["name"].split()[0] == brand]
        rest = [o for o in pool if o["name"].split()[0] != brand]
        # 형제 모델은 3개까지만: 모델이 많은 브랜드가 6칸을 다 채우면 다른 브랜드 모델이 링크를 못 받는다.
        others = siblings[:3] + rest[:6 - len(siblings[:3])]
        os.makedirs(m["slug"], exist_ok=True)
        path = os.path.join(m["slug"], "index.html")
        with open(path, "w", encoding="utf-8") as f:
            f.write(build(m, others))
        print("wrote", path)

    print()
    print("사이트맵을 갱신하려면: python3 build_sitemap.py")
